package server

import "net/http"

// NewHandler builds the top-level HTTP handler for the syncbox server.
func NewHandler(cfg Config) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", handleHealthz)
	return mux
}

func handleHealthz(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

package server

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"strconv"
)

const defaultPort = 8080

// Config holds the server's runtime configuration.
type Config struct {
	DataDir string
	Port    int
}

// ParseConfig parses server configuration from CLI flags, falling back to
// SYNCBOX_DATA_DIR/SYNCBOX_PORT environment variables when the corresponding
// flag is not given.
func ParseConfig(args []string) (Config, error) {
	fs := flag.NewFlagSet("syncbox-server", flag.ContinueOnError)

	envPort := defaultPort
	if v := os.Getenv("SYNCBOX_PORT"); v != "" {
		p, err := strconv.Atoi(v)
		if err != nil {
			return Config{}, fmt.Errorf("invalid SYNCBOX_PORT %q: %w", v, err)
		}
		envPort = p
	}

	dataDir := fs.String("data-dir", os.Getenv("SYNCBOX_DATA_DIR"), "path to the data directory (required; env SYNCBOX_DATA_DIR)")
	port := fs.Int("port", envPort, "port to listen on (default 8080; env SYNCBOX_PORT)")

	if err := fs.Parse(args); err != nil {
		return Config{}, err
	}

	if *dataDir == "" {
		return Config{}, errors.New("--data-dir is required (or set SYNCBOX_DATA_DIR)")
	}

	return Config{DataDir: *dataDir, Port: *port}, nil
}

package main

import (
	"fmt"
	"log"
	"net/http"
	"os"

	"syncbox/internal/server"
)

func main() {
	cfg, err := server.ParseConfig(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, "syncbox-server:", err)
		os.Exit(1)
	}

	if info, err := os.Stat(cfg.DataDir); err != nil || !info.IsDir() {
		fmt.Fprintf(os.Stderr, "syncbox-server: data dir %q is not accessible: %v\n", cfg.DataDir, err)
		os.Exit(1)
	}

	addr := fmt.Sprintf(":%d", cfg.Port)
	handler := server.NewHandler(cfg)

	log.Printf("syncbox-server: listening on %s, data-dir=%s", addr, cfg.DataDir)
	if err := http.ListenAndServe(addr, handler); err != nil {
		fmt.Fprintln(os.Stderr, "syncbox-server:", err)
		os.Exit(1)
	}
}

package server

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestHealthz(t *testing.T) {
	handler := NewHandler(Config{DataDir: "/tmp", Port: 8080})

	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Errorf("status = %d, want %d", rec.Code, http.StatusOK)
	}
}

